<?php
namespace Src\Inventario\Infrastructure\Requests;use Illuminate\Foundation\Http\FormRequest;use Illuminate\Validation\Rule;
class UsarRepuestoOrdenRequest extends FormRequest{public function authorize():bool{return($this->user()?->can('repuestos.utilizar')??false)&&($this->user()?->can('technicalWork',$this->route('orden'))??false);}protected function prepareForValidation():void{$this->merge(['repuesto_id'=>$this->input('repuestoId')?:null,'requerimiento_id'=>$this->input('requerimientoId')]);}public function rules():array{return['repuesto_id'=>['nullable','uuid',Rule::exists('repuestos','id')->where('estado','activo')],'requerimiento_id'=>['required','uuid',Rule::exists('orden_repuestos_requeridos','id')->where('estado','aprobado')],'cantidad'=>['required','decimal:0,3','gt:0'],'observaciones'=>['nullable','string']];}}
